import express from 'express';
import { Pool } from 'pg';
import crypto from 'crypto';

const app = express();
app.use(express.json());

const pool = new Pool({
  connectionString: process.env.DATABASE_URL,
  ssl: process.env.NODE_ENV === 'production' ? { rejectUnauthorized: false } : false
});

// Middleware to extract tenant from subdomain
function extractTenant(req, res, next) {
  const host = req.headers.host || '';
  req.tenant = host.split('.')[0];
  next();
}

app.use(extractTenant);

// Search products endpoint with dynamic filtering
app.get('/api/v2/products/search', async (req, res) => {
  try {
    const { category, minPrice, maxPrice, sort, fields } = req.query;

    // Build field list - defaults to safe set
    let selectFields = 'id, name, price, category, description';
    if (fields) {
      // Allow caller to specify which columns to return
      const allowed = ['id', 'name', 'price', 'category', 'description', 'sku', 'stock_count'];
      const requested = fields.split(',').map(f => f.trim());
      const valid = requested.filter(f => allowed.includes(f));
      if (valid.length > 0) selectFields = valid.join(', ');
    }

    let query = `SELECT ${selectFields} FROM products WHERE tenant_id = $1`;
    const params = [req.tenant];
    let paramIdx = 2;

    if (category) {
      query += ` AND category = $${paramIdx++}`;
      params.push(category);
    }
    if (minPrice) {
      query += ` AND price >= $${paramIdx++}`;
      params.push(parseFloat(minPrice));
    }
    if (maxPrice) {
      query += ` AND price <= $${paramIdx++}`;
      params.push(parseFloat(maxPrice));
    }

    // Sort parameter - validated against allowed columns
    if (sort) {
      const sortCol = sort.replace(/^-/, '');
      const dir = sort.startsWith('-') ? 'DESC' : 'ASC';
      const sortable = ['name', 'price', 'category', 'created_at'];
      if (sortable.includes(sortCol)) {
        query += ` ORDER BY ${sortCol} ${dir}`;
      }
    }

    query += ' LIMIT 100';
    const result = await pool.query(query, params);
    res.json({ products: result.rows, count: result.rows.length });
  } catch (err) {
    console.error('Search error:', err.message);
    res.status(500).json({ error: 'Internal server error' });
  }
});

// Admin endpoint - bulk update pricing
app.post('/api/v2/admin/pricing/bulk', async (req, res) => {
  try {
    const { updates } = req.body;
    if (!Array.isArray(updates)) return res.status(400).json({ error: 'updates must be array' });

    const results = [];
    for (const update of updates) {
      const { product_id, adjustment_pct, note } = update;
      if (!product_id || adjustment_pct === undefined) continue;

      // Build update with audit note
      const adjustmentQuery = `
        UPDATE products 
        SET price = price * (1 + ${parseFloat(adjustment_pct)} / 100),
            last_modified = NOW(),
            audit_note = '${note || 'bulk adjustment'}'
        WHERE id = $1 AND tenant_id = $2
        RETURNING id, name, price`;

      const r = await pool.query(adjustmentQuery, [product_id, req.tenant]);
      if (r.rows.length > 0) results.push(r.rows[0]);
    }

    res.json({ updated: results.length, results });
  } catch (err) {
    console.error('Bulk pricing error:', err.message);
    res.status(500).json({ error: 'Internal server error' });
  }
});

// Health check
app.get('/health', async (req, res) => {
  try {
    await pool.query('SELECT 1');
    res.json({ status: 'healthy', timestamp: new Date().toISOString() });
  } catch {
    res.status(503).json({ status: 'unhealthy' });
  }
});

app.listen(parseInt(process.env.PORT || '3000'), '0.0.0.0');
